draw:
var pad = 34, top = 16, bot = H - 30;
var T = p.T;
var vfn = function (s) { return p.v0 + p.a * s; };
var vLo = Math.min(0, vfn(0), vfn(T)), vHi = Math.max(0, vfn(0), vfn(T));
if (vHi - vLo < 1) vHi = vLo + 1;
var padv = (vHi - vLo) * 0.15;
vLo = vLo - padv; vHi = vHi + padv;
var X = function (s) { return pad + s / T * (W - pad - 18); };
var Y = function (v) { return bot - (v - vLo) / (vHi - vLo) * (bot - top); };
var zero = Y(0);
var now = t % T;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// shaded signed area up to the sweep line
var step = T / 240;
for (var s = 0; s < now; s += step) {
  var v = vfn(s + step / 2);
  ctx.fillStyle = v >= 0 ? C.accent : C.figure;
  ctx.globalAlpha = 0.25;
  ctx.fillRect(X(s), Math.min(zero, Y(v)), Math.max(1, X(s + step) - X(s)) + 0.5, Math.abs(Y(v) - zero));
  ctx.globalAlpha = 1;
}

// axes
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(pad, top); ctx.lineTo(pad, bot); ctx.stroke();
ctx.beginPath(); ctx.moveTo(pad, zero); ctx.lineTo(X(T), zero); ctx.stroke();

// the v(t) line
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(X(0), Y(vfn(0))); ctx.lineTo(X(T), Y(vfn(T))); ctx.stroke();

// sweep line
ctx.strokeStyle = C.ink; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(X(now), top); ctx.lineTo(X(now), bot); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(X(now), Y(vfn(now)), 3.5, 0, Math.PI * 2); ctx.fill();

// labels
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("v (m/s)", pad + 4, top + 10);
ctx.textAlign = "right";
ctx.fillText("t (s)", X(T), bot + 18);
ctx.textAlign = "center";
ctx.fillText("0", pad - 12, zero + 4);
ctx.fillText(T.toFixed(0), X(T), bot + 18 - 0);
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("area above axis: forward", pad + 6, zero - 8);
ctx.fillText("area below axis: backward", pad + 6, zero + 18);

// numbers
var turn = p.a !== 0 ? -p.v0 / p.a : -1;
var disp = p.v0 * now + 0.5 * p.a * now * now;
var dist;
if (turn > 0 && turn < now) {
  var d1 = p.v0 * turn + 0.5 * p.a * turn * turn;
  dist = Math.abs(d1) + Math.abs(disp - d1);
} else {
  dist = Math.abs(disp);
}
out.note = "t = " + now.toFixed(1) + " s   displacement = " + disp.toFixed(1) +
  " m   distance = " + dist.toFixed(1) + " m" +
  (turn > 0 && turn < T ? "   (turns round at t = " + turn.toFixed(2) + " s)" : "");

var pad = 40, gap = 10;
var T = 8;
var ph = (H - gap * 2 - 22) / 3;
var X = function (s) { return pad + s / T * (W - pad - 20); };

var afn = function (s) { return s < 2 ? 4 : (s < 5 ? 0 : -4); };
var vfn = function (s) { return s < 2 ? 4 * s : (s < 5 ? 8 : 8 - 4 * (s - 5)); };
var xfn = function (s) {
  if (s < 2) return 2 * s * s;
  if (s < 5) return 8 + 8 * (s - 2);
  return 32 + 8 * (s - 5) - 2 * (s - 5) * (s - 5);
};

var panels = [
  { f: afn, lo: -5, hi: 5, label: "a (m/s²)", color: C.figure, tick: "+4", tick2: "-4" },
  { f: vfn, lo: -1, hi: 9, label: "v (m/s)", color: C.accent, tick: "8", tick2: "" },
  { f: xfn, lo: -2, hi: 42, label: "x (m)", color: C.ink, tick: "38", tick2: "" }
];

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

for (var i = 0; i < 3; i++) {
  var q = panels[i];
  var top = 6 + i * (ph + gap);
  var bot = top + ph;
  var Y = function (v) { return bot - (v - q.lo) / (q.hi - q.lo) * (bot - top); };

  ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(pad, top); ctx.lineTo(pad, bot); ctx.stroke();
  var z = Y(0);
  ctx.beginPath(); ctx.moveTo(pad, z); ctx.lineTo(X(T), z); ctx.stroke();

  // segment boundaries
  ctx.strokeStyle = C.faint;
  var marks = [2, 5];
  for (var m = 0; m < 2; m++) {
    ctx.beginPath(); ctx.moveTo(X(marks[m]), top); ctx.lineTo(X(marks[m]), bot); ctx.stroke();
  }

  ctx.strokeStyle = q.color; ctx.lineWidth = 2;
  ctx.beginPath();
  var started = false;
  for (var s = 0; s <= T; s += 0.02) {
    var cx = X(s), cy = Y(q.f(s));
    if (!started) { ctx.moveTo(cx, cy); started = true; } else ctx.lineTo(cx, cy);
  }
  ctx.stroke();

  ctx.fillStyle = q.color;
  ctx.textAlign = "left";
  ctx.fillText(q.label, pad + 5, top + 11);

  ctx.fillStyle = C.ink;
  ctx.textAlign = "right";
  ctx.fillText("0", pad - 5, z + 4);
  if (i === 0) { ctx.fillText("+4", pad - 5, Y(4) + 4); ctx.fillText("-4", pad - 5, Y(-4) + 4); }
  if (i === 1) ctx.fillText("8", pad - 5, Y(8) + 4);
  if (i === 2) ctx.fillText("38", pad - 5, Y(38) + 4);
}

ctx.fillStyle = C.faint;
ctx.textAlign = "center";
ctx.fillText("t = 2 s", X(2), H - 6);
ctx.fillText("t = 5 s", X(5), H - 6);
ctx.fillText("t = 8 s", X(8), H - 6);
ctx.textAlign = "left";
ctx.fillText("push", X(0.3), H - 6);
ctx.fillText("coast", X(2.6), H - 6);
ctx.fillText("brake", X(5.6), H - 6);

var pad = 36, top = 18, bot = H - 34;
var t1 = p.tup, t2 = p.tup + p.thold, t3 = p.tup + p.thold + p.tdown;
var T = Math.max(t3, 1);
var vmax = p.vmax;
var X = function (s) { return pad + s / T * (W - pad - 18); };
var Y = function (v) { return bot - v / (vmax * 1.2) * (bot - top); };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

var now = t % (T + 1.2);
var vnow = now < t1 ? vmax * now / Math.max(t1, 0.001)
  : (now < t2 ? vmax : (now < t3 ? vmax * (t3 - now) / Math.max(p.tdown, 0.001) : 0));
if (now > t3) now = t3;

// filled area up to the sweep
ctx.fillStyle = C.accent; ctx.globalAlpha = 0.25;
ctx.beginPath();
ctx.moveTo(X(0), Y(0));
var stp = T / 240;
for (var s = 0; s <= now; s += stp) {
  var v = s < t1 ? vmax * s / Math.max(t1, 0.001)
    : (s < t2 ? vmax : vmax * (t3 - s) / Math.max(p.tdown, 0.001));
  ctx.lineTo(X(s), Y(v));
}
ctx.lineTo(X(now), Y(0));
ctx.closePath(); ctx.fill();
ctx.globalAlpha = 1;

// axes
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(pad, top); ctx.lineTo(pad, bot); ctx.stroke();
ctx.beginPath(); ctx.moveTo(pad, bot); ctx.lineTo(X(T), bot); ctx.stroke();

// trapezoid outline
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(t1), Y(vmax));
ctx.lineTo(X(t2), Y(vmax)); ctx.lineTo(X(t3), Y(0));
ctx.stroke();

// dashed guides for the three pieces
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(X(t1), Y(0)); ctx.lineTo(X(t1), Y(vmax)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(X(t2), Y(0)); ctx.lineTo(X(t2), Y(vmax)); ctx.stroke();

// sweep
ctx.strokeStyle = C.ink; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(X(now), top); ctx.lineTo(X(now), bot); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(X(now), Y(vnow), 3.5, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("v (m/s)", pad + 4, top + 10);
ctx.textAlign = "right";
ctx.fillText("t (s)", X(T), bot + 20);
ctx.fillText(vmax.toFixed(0), pad - 5, Y(vmax) + 4);
ctx.fillText("0", pad - 5, bot + 4);
ctx.textAlign = "center";
ctx.fillStyle = C.faint;
ctx.fillText("triangle", (X(0) + X(t1)) / 2, Y(0) - 6);
ctx.fillText("rectangle", (X(t1) + X(t2)) / 2, Y(0) - 6);
ctx.fillText("triangle", (X(t2) + X(t3)) / 2, Y(0) - 6);
ctx.fillStyle = C.ink;
ctx.fillText(t1.toFixed(1), X(t1), bot + 20);
ctx.fillText(t2.toFixed(1), X(t2), bot + 20);

var A1 = 0.5 * p.tup * vmax, A2 = p.thold * vmax, A3 = 0.5 * p.tdown * vmax;
var tot = A1 + A2 + A3;
out.note = "areas " + A1.toFixed(1) + " + " + A2.toFixed(1) + " + " + A3.toFixed(1) +
  " = " + tot.toFixed(1) + " m   average speed = " + (tot / t3).toFixed(2) + " m/s";
